<!--
  GearSwap Atelier · a block both optimizers share (blocks.ts): the limits' tiles, the search, or the pieces the try changes.

  @file    atelier/src/screens/optimizer/OptBlocks.svelte
  @author  ejouanchicot
-->
<script lang="ts">
  import {selSync} from '../../components/selsync';
  import type {LimitsView, ChangesView, SearchView} from './blocks';

  let {limits = null, changes = null, search = null}: {limits?: LimitsView | null; changes?: ChangesView | null; search?: SearchView | null} = $props();
</script>

{#if limits}<h3 class="ophd" title={limits.titleTip || undefined}>{limits.title}</h3><div class="oplimits {limits.many ? 'many' : ''}">{#each limits.tiles as x, i (i)}<label class="oplim" title={x.tip}><span class="oplimn">{x.name}</span><span class="oplimv">{#if x.sign}<i>{x.sign}</i>{/if}<input type="number" step="1" {...x.attr} value={x.value}></span></label>{/each}</div>{/if}{#if changes}<h4 class="ophd2">{@html changes.title}</h4><ul class="opchg">{#each changes.rows as r, i (i)}<li title={r.slot + ' : ' + r.from + ' ' + r.to}><span class="sl">{r.slot}</span><span class="to">{r.to.replace(/^→\s*/, '')}</span><span class="fr">{r.from}</span></li>{/each}</ul>{/if}{#if search}{@const q = search}<h4 class="ophd2">{@html q.title}</h4><div class="seg optabs" role="group">{#each q.tabs as x (x.id)}<button data-optab={x.id} aria-pressed={x.pressed} title={x.tip}>{x.label}{#if x.on}<small class="opon">{x.on}</small>{/if}</button>{/each}</div><div class="optab">{#if q.menu}{@const m = q.menu}<div class="opsels"><span title={m.tip || undefined}>{m.label}</span><select class="buffsel" data-optopt={m.key} title={m.tip || undefined} use:selSync={(m.options.find(o => o.selected) || {value: undefined}).value}>{#each m.options as o (o.value)}<option value={o.value} selected={o.selected}>{o.label}</option>{/each}</select></div>{/if}<div class="opsws">{#each q.switches as x (x.k)}<label class="opsw {x.off ? 'off' : ''}" title={x.tip || undefined}><input type="checkbox" disabled={x.off} data-optopt={x.off ? undefined : x.k} checked={!x.off && x.checked}><span>{x.label}</span></label>{/each}</div>{#if q.ranks}{@const k = q.ranks}<div class="opranks"><div class="opranksbar"><span class="opranksh" title={k.tip}>{k.title}</span><span class="sp"></span><button class="linkbtn" data-optrankall="max">{k.allMax}</button><button class="linkbtn" data-optrankall="off">{k.allOff}</button></div>{#each k.kinds as g (g.label)}<h5 class="oprankk">{g.label}</h5>{#each g.rows as r (r.fam)}<div class="oprank">{@html r.iconHtml}<div class="opranki"><b>{r.label}</b><small><span>{r.count}</span> · <span title={r.mineTip || undefined}>{r.mine}</span></small></div><div class="oprankc" role="radiogroup" aria-label={r.label}>{#each r.chips as c (c.value)}<button class="rkchip" class:on={c.on} class:off={c.value === 'off'} role="radio" aria-checked={c.on} data-optrank={r.fam} data-v={c.value} title={c.title}>{c.label}</button>{/each}</div></div>{/each}{/each}</div>{/if}{#if q.special}<p class="muted small">{q.special}</p>{/if}{#if q.locks}<p class="oplocks">{q.locks.text + ' '}<button class="linkbtn" data-locksclear>{q.locks.clear}</button></p>{/if}{#if q.excl}{@const x = q.excl}<div class="opexclbox"><div class="opranksbar"><span class="opranksh">{x.label} · {x.count}</span><span class="muted small">{x.back}</span><span class="sp"></span>{#if x.clear}<button class="linkbtn" data-exclclear>{x.clear}</button>{/if}</div>{#each x.groups as g (g.slot)}<div class="opexclg"><h5 class="oprankk">{g.label}<small>{g.count}</small></h5><div class="opexclchips">{#each g.items as it (it.n)}<button class="opexclchip" data-unexclude={it.n} title={it.tip}>{@html it.iconHtml}<span>{it.n}</span>{#if it.why}<em>{it.why}</em>{/if}<i aria-hidden="true">✕</i></button>{/each}{#if g.more}<button class="linkbtn opexclmore" data-exclmore={g.slot}>{g.more.label}</button>{/if}</div></div>{/each}</div>{/if}</div>{/if}
